let rollingMode='single',rollingSpeed=12,rollingPaused=false,rollingFrame=0,rollingLast=0,rollingKey='',rollingPosition=0;
try{const preference=JSON.parse(localStorage.getItem('romano-bosanski-reading')||'{}');rollingMode=preference.mode==='scroll'?'scroll':'single';rollingSpeed=Math.max(5,Math.min(45,Number(preference.speed)||12));}catch{}
function saveRollingPreference(){try{localStorage.setItem('romano-bosanski-reading',JSON.stringify({mode:rollingMode,speed:rollingSpeed}));}catch{}}
function stopRolling(){if(rollingFrame)cancelAnimationFrame(rollingFrame);rollingFrame=0;rollingLast=0;}
function syncRollingPosition(){
 if(lastPage!=='bosanski'||rollingMode!=='scroll')return;
 const box=$('bosanskiRolling'),target=$('rolling-'+currentAyah);
 if(!box||!target||box.hidden)return;
 // Position relative to scrolling container, NOT offsetParent; prevent losing the verse.
 const b=box.getBoundingClientRect(),t=target.getBoundingClientRect();
 const desired=box.scrollTop+(t.top-b.top)-Math.max(18,(box.clientHeight-Math.min(target.offsetHeight,box.clientHeight))*.40);
 const max=Math.max(0,box.scrollHeight-box.clientHeight);
 const position=Math.min(max,Math.max(0,desired));
 if(Math.abs(position-box.scrollTop)>5)box.scrollTo({top:position,behavior:'auto'});
}
function startRolling(){stopRolling();syncRollingPosition();}
function rollingControls(){const visible=lastPage==='bosanski';$('bosanskiReadMode').checked=rollingMode==='scroll';$('bosanskiRolling').hidden=!visible||rollingMode!=='scroll';$('bosanskiFocus').hidden=!visible||rollingMode!=='single';if(visible&&rollingMode==='scroll')requestAnimationFrame(()=>requestAnimationFrame(syncRollingPosition));}
function renderRolling(){const identity=audioSura+':'+edition;if(rollingKey===identity)return;rollingKey=identity;$('bosanskiRollingText').innerHTML=Array.from({length:count(audioSura)},(_,i)=>{const a=i+1,k=key(audioSura,a),text=D.mlivo[k];return '<article class="rolling-verse" id="rolling-'+a+'"><p class="verse-ref">'+escape(title(audioSura))+' · '+k+'</p><p lang="bs">'+escape(text||'O birimo prjevod baš akava ajet panda nane unesome.')+'</p></article>';}).join('');$('bosanskiRolling').scrollTop=0;}
function seekRolling(){requestAnimationFrame(syncRollingPosition);}
