 const targets=[[$('readerBody'),$('reader-'+s+'-'+a),$('readerVerses')],[$('romaneBody'),$('romane-'+s+'-'+a),$('romaneVerses')],[$('audioVerses'),$('audio-'+s+'-'+a),$('audioVerses')],[$('bosanskiRolling'),$('rolling-'+a),$('bosanskiRollingText')]];
