function normalizeSearch(t){return String(t).toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'dj').replace(/[’‘]/g,"'").replace(/\s+/g,' ').trim();}
const unifiedSearchIndex=[['rom',D.romane],['mlivo',D.mlivo]].flatMap(([ed,source])=>Object.entries(source).map(([k,t])=>({ed,k,t,normalized:normalizeSearch(t)})));
let searchTimer;
function riSearchRoute(name){if(typeof window.romanoApp?.openRoute==='function')window.romanoApp.openRoute(name);else if(location.hash!=='#'+name)location.hash=name;else route();}
function searchAllVerses(){
 clearTimeout(searchTimer);const q=normalizeSearch($('verseSearchInput').value),results=$('verseSearchResults');results.replaceChildren();
 if(!q){$('verseSearchStatus').textContent='';return;}
 const found=new Map();for(const m of unifiedSearchIndex){if(m.normalized.includes(q)){const identity=m.ed+':'+m.k;if(!found.has(identity))found.set(identity,m);}}
 const matches=[...found.values()].sort((x,y)=>{const a=x.k.split(':').map(Number),b=y.k.split(':').map(Number);return a[0]-b[0]||a[1]-b[1]||(x.ed===y.ed?0:x.ed==='rom'?-1:1)});
 $('verseSearchStatus').textContent=matches.length+' · Romane hem Bosanski';let shown=0;
 function more(){
  for(const {ed,k,t} of matches.slice(shown,shown+100)){
   const [s,a]=k.split(':').map(Number),b=document.createElement('button');b.className='surah-row';b.type='button';b.dataset.searchLanguage=ed==='rom'?'rom':'bs';
   b.textContent=(ed==='rom'?'Romane':translationNames[ed])+' · '+title(s)+' · '+k+' — '+t;
   b.onclick=()=>{manualUntil=Date.now()+8000;searchDialog.close();if(ed==='rom'){renderRomane(s,a);riSearchRoute('romane');}else{edition=ed;settings.readerCompare=false;renderReader(s,a);riSearchRoute('reader');}};results.append(b);
  }
  shown+=100;if(shown<matches.length){const b=document.createElement('button');b.className='button';b.textContent='Sikav panda';b.onclick=()=>{b.remove();more();};results.append(b);}
 }
 more();
}
$('verseSearchForm').onsubmit=e=>{e.preventDefault();searchAllVerses();};
$('verseSearchInput').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(searchAllVerses,180);});

window.riFlightResolveSource=async function(rec,n){
  const nn=String(n).padStart(3,'0');
  if(romanoNewReciters[rec])return (await romanoFindRecording(rec,n)).url;
  if(rec==='jazairi')return 'https://cdn.mp3quran.net/audio/yassen-jazairi/r1/'+nn+'.mp3';
  if(rec==='maher')return 'https://cdn.mp3quran.net/audio/maher-muaiqly/r3/'+nn+'.mp3';
  if(rec==='kurdi')return 'https://cdn.mp3quran.net/audio/raad-kurdi/r1/'+nn+'.mp3';
  throw Error('MP3Quran nema potvrđen snimak za ovog učača.');
 };
